import itertools, sys
sys.path.insert(0,'/tmp/fz')
from obs import OBS

def base_order(head, lst):
    return [head] + [x for x in lst if x != head]

def char_bonus(t, i, P):
    c = t[i]
    if i == 0: return P['START']
    p = t[i-1]
    if p == '/': return P['SLASH']
    if p in '-_.': return P['SEP']
    if p.islower() and c.isupper(): return P['CAMEL']
    return 0

def score_align(q, t, positions, P, opts):
    s = 0
    ql = q.lower()
    for k, i in enumerate(positions):
        s += P['BASE'] + char_bonus(t, i, P)
        if k > 0:
            prev = positions[k-1]
            if i == prev + 1: s += P['CONSEC']
            else:
                gapchars = t[prev+1:i]
                if opts['sepfree']: gapchars = [c for c in gapchars if c not in '/-_.']
                if opts['gapmode'] == 'len': s -= P['GAP'] * len(gapchars)
                elif opts['gapmode'] == 'count': s -= P['GAP'] * (1 if len(gapchars) > 0 or not opts['sepfree'] else 0) if False else P['GAP']
        if t[i] != q[k]: s -= P['MISMATCH']
    if opts['lead']: s -= P['LEAD'] * positions[0]
    return s

def all_alignments(q, t):
    ql = q.lower(); tl = t.lower()
    res = []
    def rec(qi, start, acc):
        if qi == len(ql):
            res.append(list(acc)); return
        for i in range(start, len(tl)):
            if tl[i] == ql[qi]:
                acc.append(i); rec(qi+1, i+1, acc); acc.pop()
    rec(0, 0, [])
    return res

def greedy(q, t):
    ql = q.lower(); tl = t.lower(); pos=[]; qi=0
    for i,c in enumerate(tl):
        if qi < len(ql) and c == ql[qi]: pos.append(i); qi+=1
    return pos if qi == len(ql) else None

def total(q, t, P, opts):
    if opts['align'] == 'greedy':
        pos = greedy(q, t)
        if pos is None: return None
        s = score_align(q, t, pos, P, opts)
    else:
        als = all_alignments(q, t)
        if not als: return None
        s = max(score_align(q, t, a, P, opts) for a in als)
    ql = q.lower(); tl = t.lower()
    if tl == ql: s += P['EXACT']
    if tl.startswith(ql): s += P['PREFIX']
    if ql in tl: s += P['SUBSTR']
    if opts['len']: s -= P['LEN'] * len(t)
    return s

def check(P, opts):
    for q, head, lst, observed in OBS:
        base = base_order(head, lst)
        scored = []
        for t in base:
            s = total(q, t, P, opts)
            if s is not None: scored.append((t, s))
        scored.sort(key=lambda x: -x[1])  # stable
        if [t for t,_ in scored] != observed: return False
    return True

