use anyhow::{anyhow, Context, Result};
use git2::{BranchType, Oid, Repository, Sort, StatusOptions};
use std::collections::HashMap;

pub const MAX_COMMITS: usize = 500;
pub const MAX_FILES: usize = 50;

#[derive(Debug, Clone)]
pub struct CommitInfo {
    pub oid: Oid,
    pub short: String,
    pub summary: String,
    pub message: String,
    pub author_name: String,
    pub author_email: String,
    pub time: i64,
    pub parents: Vec<Oid>,
}

#[derive(Debug, Clone)]
pub struct BranchEntry {
    /// Display / sort name, e.g. "main", "origin/feature", "upstream/x"
    pub name: String,
    pub is_remote: bool,
    /// Some(remote) when a local branch is merged with its remote counterpart
    pub merged_remote: Option<String>,
    pub is_head: bool,
}

impl BranchEntry {
    pub fn display_name(&self) -> String {
        match &self.merged_remote {
            Some(r) => format!("{} \u{2194} {}", self.name, r),
            None => self.name.clone(),
        }
    }
}

#[derive(Debug, Clone, PartialEq)]
pub enum HeadState {
    Unborn,
    Detached(Oid),
    Branch(String, Oid),
}

impl HeadState {
    pub fn oid(&self) -> Option<Oid> {
        match self {
            HeadState::Unborn => None,
            HeadState::Detached(o) => Some(*o),
            HeadState::Branch(_, o) => Some(*o),
        }
    }
    pub fn branch_name(&self) -> Option<&str> {
        match self {
            HeadState::Branch(n, _) => Some(n.as_str()),
            _ => None,
        }
    }
}

#[derive(Debug, Clone)]
pub struct RepoData {
    pub repo_name: String,
    pub head: HeadState,
    pub commits: Vec<CommitInfo>,
    pub branches: HashMap<Oid, Vec<BranchEntry>>,
    pub uncommitted_count: usize,
}

#[derive(Debug, Clone)]
pub struct FileChange {
    pub status: char,
    pub path: String,
    pub stats: Option<(usize, usize)>,
}

#[derive(Debug, Clone, Default)]
pub struct DiffSummary {
    pub files_changed: usize,
    pub insertions: usize,
    pub deletions: usize,
    pub files: Vec<FileChange>,
    pub more: usize,
}

pub struct Git {
    pub repo: Repository,
}

impl Git {
    pub fn open() -> Result<Self> {
        let repo = Repository::discover(".")
            .context("Git repository not found. Please run inside a Git repository.")?;
        Ok(Self { repo })
    }

    pub fn repo_name(&self) -> String {
        let path = match self.repo.workdir() {
            Some(w) => w.to_path_buf(),
            None => self.repo.path().to_path_buf(),
        };
        let mut p = path.clone();
        // strip trailing slash
        if let Some(name) = p.file_name() {
            return name.to_string_lossy().to_string();
        }
        p.pop();
        p.file_name()
            .map(|n| n.to_string_lossy().to_string())
            .unwrap_or_default()
    }

    pub fn head_state(&self) -> HeadState {
        match self.repo.head() {
            Ok(r) => {
                let oid = match r.target() {
                    Some(o) => o,
                    None => return HeadState::Unborn,
                };
                if self.repo.head_detached().unwrap_or(false) {
                    HeadState::Detached(oid)
                } else {
                    let name = r.shorthand().unwrap_or("HEAD").to_string();
                    HeadState::Branch(name, oid)
                }
            }
            Err(_) => HeadState::Unborn,
        }
    }

    pub fn load(&self) -> Result<RepoData> {
        let head = self.head_state();
        let head_branch = head.branch_name().map(|s| s.to_string());

        // collect branches
        let mut locals: Vec<(String, Oid)> = Vec::new();
        let mut remotes: Vec<(String, Oid)> = Vec::new();
        for b in self.repo.branches(None)? {
            let (branch, kind) = match b {
                Ok(x) => x,
                Err(_) => continue,
            };
            let r = branch.get();
            if r.symbolic_target().is_some() {
                continue;
            }
            let Some(oid) = r.target() else { continue };
            let Ok(Some(name)) = branch.name() else { continue };
            match kind {
                BranchType::Local => locals.push((name.to_string(), oid)),
                BranchType::Remote => remotes.push((name.to_string(), oid)),
            }
        }

        // revwalk
        let mut commits = Vec::new();
        {
            let mut walk = self.repo.revwalk()?;
            walk.set_sorting(Sort::TOPOLOGICAL | Sort::TIME)?;
            for (_, oid) in locals.iter().chain(remotes.iter()) {
                let _ = walk.push(*oid);
            }
            for oid in walk.flatten() {
                if commits.len() >= MAX_COMMITS {
                    break;
                }
                if let Ok(c) = self.repo.find_commit(oid) {
                    commits.push(commit_info(&c));
                }
            }
        }

        // branch entries per commit
        let mut branches: HashMap<Oid, Vec<BranchEntry>> = HashMap::new();
        for (name, oid) in &locals {
            branches.entry(*oid).or_default().push(BranchEntry {
                name: name.clone(),
                is_remote: false,
                merged_remote: None,
                is_head: head_branch.as_deref() == Some(name.as_str()),
            });
        }
        for (name, oid) in &remotes {
            let entries = branches.entry(*oid).or_default();
            let mut merged = false;
            if let Some(rest) = name.strip_prefix("origin/") {
                if let Some(e) = entries
                    .iter_mut()
                    .find(|e| !e.is_remote && e.name == rest && e.merged_remote.is_none())
                {
                    e.merged_remote = Some("origin".to_string());
                    merged = true;
                }
            }
            if !merged {
                entries.push(BranchEntry {
                    name: name.clone(),
                    is_remote: true,
                    merged_remote: None,
                    is_head: false,
                });
            }
        }
        for entries in branches.values_mut() {
            entries.sort_by(|a, b| {
                b.is_head
                    .cmp(&a.is_head)
                    .then_with(|| a.name.as_bytes().cmp(b.name.as_bytes()))
            });
        }

        let uncommitted_count = self.uncommitted_count();

        Ok(RepoData {
            repo_name: self.repo_name(),
            head,
            commits,
            branches,
            uncommitted_count,
        })
    }

    fn uncommitted_count(&self) -> usize {
        if self.repo.is_bare() {
            return 0;
        }
        let mut opts = StatusOptions::new();
        opts.include_untracked(false)
            .include_ignored(false)
            .recurse_untracked_dirs(false)
            .exclude_submodules(true);
        match self.repo.statuses(Some(&mut opts)) {
            Ok(st) => st
                .iter()
                .filter(|e| {
                    let s = e.status();
                    !s.is_empty() && !s.is_ignored() && !s.is_wt_new()
                })
                .count(),
            Err(_) => 0,
        }
    }

    pub fn commit_diff(&self, oid: Oid) -> Result<DiffSummary> {
        let commit = self.repo.find_commit(oid)?;
        let tree = commit.tree()?;
        let parent_tree = if commit.parent_count() > 0 {
            Some(commit.parent(0)?.tree()?)
        } else {
            None
        };
        let diff = self
            .repo
            .diff_tree_to_tree(parent_tree.as_ref(), Some(&tree), None)?;
        Ok(summarize(&diff))
    }

    pub fn uncommitted_diff(&self) -> Result<DiffSummary> {
        let head_tree = match self.repo.head() {
            Ok(h) => h.peel_to_tree().ok(),
            Err(_) => None,
        };
        let cached = self
            .repo
            .diff_tree_to_index(head_tree.as_ref(), None, None)?;
        let mut opts = git2::DiffOptions::new();
        opts.include_untracked(false);
        let workdir = self.repo.diff_index_to_workdir(None, Some(&mut opts))?;
        let a = summarize(&cached);
        let b = summarize(&workdir);
        let mut files = a.files.clone();
        for f in b.files {
            if !files.iter().any(|x| x.path == f.path) {
                files.push(f);
            }
        }
        Ok(DiffSummary {
            files_changed: files.len(),
            insertions: a.insertions + b.insertions,
            deletions: a.deletions + b.deletions,
            more: 0,
            files,
        })
    }

    pub fn create_branch(&self, name: &str, oid: Oid) -> Result<()> {
        let commit = self.repo.find_commit(oid)?;
        self.repo.branch(name, &commit, false)?;
        Ok(())
    }

    pub fn delete_branch(&self, name: &str) -> Result<()> {
        let mut b = self.repo.find_branch(name, BranchType::Local)?;
        b.delete()?;
        Ok(())
    }

    pub fn checkout_local_branch(&self, name: &str) -> Result<()> {
        let refname = format!("refs/heads/{}", name);
        let reference = self.repo.find_reference(&refname)?;
        let obj = reference.peel(git2::ObjectType::Commit)?;
        let mut cb = git2::build::CheckoutBuilder::new();
        self.repo.checkout_tree(&obj, Some(&mut cb))?;
        self.repo.set_head(&refname)?;
        Ok(())
    }

    pub fn checkout_commit(&self, oid: Oid) -> Result<()> {
        let obj = self.repo.find_object(oid, None)?;
        let mut cb = git2::build::CheckoutBuilder::new();
        self.repo.checkout_tree(&obj, Some(&mut cb))?;
        self.repo.set_head_detached(oid)?;
        Ok(())
    }

    /// Checkout a remote branch like "origin/feature": create or update the local branch.
    pub fn checkout_remote_branch(&self, remote_name: &str, oid: Oid) -> Result<()> {
        let local = match remote_name.find('/') {
            Some(i) => &remote_name[i + 1..],
            None => remote_name,
        };
        if local.is_empty() {
            return Err(anyhow!("invalid remote branch name"));
        }
        let commit = self.repo.find_commit(oid)?;
        match self.repo.find_branch(local, BranchType::Local) {
            Ok(mut b) => {
                if b.get().target() != Some(oid) {
                    b.get_mut()
                        .set_target(oid, &format!("keifu: update {} to {}", local, remote_name))?;
                }
            }
            Err(_) => {
                let mut b = self.repo.branch(local, &commit, false)?;
                let _ = b.set_upstream(Some(remote_name));
            }
        }
        self.checkout_local_branch(local)
    }
}

fn commit_info(c: &git2::Commit) -> CommitInfo {
    let author = c.author();
    let hex = c.id().to_string();
    CommitInfo {
        oid: c.id(),
        short: hex.chars().take(7).collect(),
        summary: c.summary().unwrap_or("").to_string(),
        message: c.message().unwrap_or("").to_string(),
        author_name: author.name().unwrap_or("").to_string(),
        author_email: author.email().unwrap_or("").to_string(),
        time: c.time().seconds(),
        parents: c.parent_ids().collect(),
    }
}

fn status_char(s: git2::Delta) -> char {
    use git2::Delta::*;
    match s {
        Added => 'A',
        Deleted => 'D',
        Modified => 'M',
        Renamed => 'R',
        Copied => 'C',
        Typechange => 'T',
        Untracked => '?',
        Ignored => '!',
        Conflicted => 'U',
        Unmodified => ' ',
        Unreadable => 'X',
    }
}

fn summarize(diff: &git2::Diff) -> DiffSummary {
    let total = diff.deltas().len();
    let mut out = DiffSummary {
        files_changed: total,
        ..Default::default()
    };
    for (idx, delta) in diff.deltas().enumerate() {
        if idx >= MAX_FILES {
            break;
        }
        let path = delta
            .new_file()
            .path()
            .or_else(|| delta.old_file().path())
            .map(|p| p.to_string_lossy().to_string())
            .unwrap_or_default();
        let status = status_char(delta.status());
        let mut stats = None;
        match git2::Patch::from_diff(diff, idx) {
            Ok(Some(patch)) => {
                let binary = patch.delta().flags().is_binary();
                if !binary {
                    if let Ok((_, add, del)) = patch.line_stats() {
                        stats = Some((add, del));
                        out.insertions += add;
                        out.deletions += del;
                    }
                }
            }
            _ => {
                if !delta.flags().is_binary() {
                    stats = Some((0, 0));
                }
            }
        }
        out.files.push(FileChange { status, path, stats });
    }
    if total > MAX_FILES {
        out.more = total - MAX_FILES;
    }
    out
}
EOF
echo ok"}

