use git2::Oid;
use ratatui::style::Color;
use std::collections::{HashMap, HashSet};

pub const NODE: char = '\u{25cf}'; // ●
pub const HEAD_NODE: char = '\u{25c9}'; // ◉
pub const VERT: char = '\u{2502}'; // │
pub const HORZ: char = '\u{2500}'; // ─
pub const CORNER_DOWN_LEFT: char = '\u{256e}'; // ╮
pub const CORNER_UP_LEFT: char = '\u{256f}'; // ╯
pub const CORNER_DOWN_RIGHT: char = '\u{256d}'; // ╭
pub const TEE_RIGHT: char = '\u{251c}'; // ├
pub const TEE_LEFT: char = '\u{2524}'; // ┤
pub const TEE_UP: char = '\u{2534}'; // ┴
pub const CROSS: char = '\u{253c}'; // ┼

const PALETTE: [Color; 9] = [
    Color::Green,
    Color::Magenta,
    Color::Yellow,
    Color::Red,
    Color::LightCyan,
    Color::LightGreen,
    Color::LightMagenta,
    Color::LightYellow,
    Color::LightRed,
];

pub fn lane_color(alloc_idx: usize) -> Color {
    if alloc_idx == 0 {
        Color::LightBlue
    } else {
        PALETTE[(alloc_idx - 1) % PALETTE.len()]
    }
}

#[derive(Debug, Clone, Copy, PartialEq)]
pub struct Cell {
    pub ch: char,
    pub color: Color,
}

#[derive(Debug, Clone)]
pub struct GraphRow {
    /// cells indexed by position (lane*2 for nodes, lane*2+1 for gaps)
    pub cells: Vec<Option<Cell>>,
    /// Some(commit index) for commit rows, None for connector rows
    pub commit: Option<usize>,
    pub lane: usize,
}

impl GraphRow {
    fn new(width: usize) -> Self {
        Self {
            cells: vec![None; width],
            commit: None,
            lane: 0,
        }
    }
    fn set(&mut self, pos: usize, ch: char, color: Color) {
        if pos >= self.cells.len() {
            self.cells.resize(pos + 1, None);
        }
        self.cells[pos] = Some(Cell { ch, color });
    }
    fn get(&self, pos: usize) -> Option<Cell> {
        self.cells.get(pos).copied().flatten()
    }
}

pub struct Graph {
    pub rows: Vec<GraphRow>,
    pub lanes: usize,
}

struct Lane {
    target: Option<Oid>,
    color: Color,
}

pub struct CommitLike<'a> {
    pub oid: Oid,
    pub parents: &'a [Oid],
}

pub fn build(commits: &[CommitLike], head_oid: Option<Oid>) -> Graph {
    let set: HashSet<Oid> = commits.iter().map(|c| c.oid).collect();
    let mut lanes: Vec<Lane> = Vec::new();
    let mut next_color = 0usize;
    let mut rows: Vec<GraphRow> = Vec::new();
    let mut max_lanes = 0usize;

    let alloc = |lanes: &mut Vec<Lane>, next_color: &mut usize, target: Oid| -> usize {
        let color = lane_color(*next_color);
        *next_color += 1;
        if let Some(i) = lanes.iter().position(|l| l.target.is_none()) {
            lanes[i] = Lane {
                target: Some(target),
                color,
            };
            i
        } else {
            lanes.push(Lane {
                target: Some(target),
                color,
            });
            lanes.len() - 1
        }
    };

    for (ci, c) in commits.iter().enumerate() {
        let positions: Vec<usize> = lanes
            .iter()
            .enumerate()
            .filter(|(_, l)| l.target == Some(c.oid))
            .map(|(i, _)| i)
            .collect();
        let lane = if positions.is_empty() {
            alloc(&mut lanes, &mut next_color, c.oid)
        } else {
            positions[0]
        };
        if positions.len() > 1 {
            // connector row joining extra lanes into `lane`
            let mut row = GraphRow::new(lanes.len() * 2);
            for (i, l) in lanes.iter().enumerate() {
                if l.target.is_some() {
                    row.set(i * 2, VERT, l.color);
                }
            }
            row.set(lane * 2, TEE_RIGHT, lanes[lane].color);
            for &p in &positions[1..] {
                let pc = lanes[p].color;
                for pos in (lane * 2 + 1)..(p * 2) {
                    if pos % 2 == 1 {
                        row.set(pos, HORZ, pc);
                    } else {
                        // lane cell
                        match row.get(pos) {
                            Some(cell) if cell.ch == VERT => row.set(pos, CROSS, cell.color),
                            Some(cell) if cell.ch == CORNER_UP_LEFT => {
                                row.set(pos, TEE_UP, cell.color)
                            }
                            Some(_) => {}
                            None => row.set(pos, HORZ, pc),
                        }
                    }
                }
                row.set(p * 2, CORNER_UP_LEFT, pc);
            }
            for &p in &positions[1..] {
                lanes[p].target = None;
            }
            max_lanes = max_lanes.max(lanes.len());
            rows.push(row);
        }

        // commit row
        let mut row = GraphRow::new(lanes.len() * 2);
        row.commit = Some(ci);
        row.lane = lane;
        for (i, l) in lanes.iter().enumerate() {
            if l.target.is_some() && i != lane {
                row.set(i * 2, VERT, l.color);
            }
        }
        let node_ch = if Some(c.oid) == head_oid { HEAD_NODE } else { NODE };
        row.set(lane * 2, node_ch, lanes[lane].color);

        let parents: Vec<Oid> = c
            .parents
            .iter()
            .copied()
            .filter(|p| set.contains(p))
            .collect();
        if parents.is_empty() {
            lanes[lane].target = None;
        } else {
            lanes[lane].target = Some(parents[0]);
            for &p in &parents[1..] {
                let existing = lanes.iter().position(|l| l.target == Some(p));
                let (j, is_new) = match existing {
                    Some(j) => (j, false),
                    None => (alloc(&mut lanes, &mut next_color, p), true),
                };
                let jc = lanes[j].color;
                if j > lane {
                    for pos in (lane * 2 + 1)..(j * 2) {
                        if pos % 2 == 1 {
                            row.set(pos, HORZ, jc);
                        } else {
                            match row.get(pos) {
                                Some(cell) if cell.ch == VERT => row.set(pos, CROSS, cell.color),
                                Some(_) => {}
                                None => row.set(pos, HORZ, jc),
                            }
                        }
                    }
                    let end = if is_new { CORNER_DOWN_LEFT } else { TEE_LEFT };
                    row.set(j * 2, end, jc);
                } else if j < lane {
                    for pos in (j * 2 + 1)..(lane * 2) {
                        if pos % 2 == 1 {
                            row.set(pos, HORZ, jc);
                        } else {
                            match row.get(pos) {
                                Some(cell) if cell.ch == VERT => row.set(pos, CROSS, cell.color),
                                Some(_) => {}
                                None => row.set(pos, HORZ, jc),
                            }
                        }
                    }
                    let end = if is_new { CORNER_DOWN_RIGHT } else { TEE_RIGHT };
                    row.set(j * 2, end, jc);
                    // the node takes the color of the target lane
                    row.set(lane * 2, node_ch, jc);
                }
            }
        }
        max_lanes = max_lanes.max(lanes.len());
        rows.push(row);
    }

    let width = max_lanes * 2;
    for r in rows.iter_mut() {
        if r.cells.len() < width {
            r.cells.resize(width, None);
        }
    }
    Graph {
        rows,
        lanes: max_lanes,
    }
}

/// Insert the "uncommitted changes" pseudo row at the top, connected to the HEAD commit row.
/// Returns true if inserted.
pub fn add_uncommitted(graph: &mut Graph, head_row: usize) -> bool {
    if head_row >= graph.rows.len() {
        return false;
    }
    let head_lane = graph.rows[head_row].lane;
    let occupied = (0..head_row).any(|r| graph.rows[r].get(head_lane * 2).is_some());
    let lane = if occupied { graph.lanes } else { head_lane };
    if occupied {
        graph.lanes += 1;
        let width = graph.lanes * 2;
        for r in graph.rows.iter_mut() {
            r.cells.resize(width, None);
        }
    }
    let gray = Color::DarkGray;
    for r in 0..head_row {
        graph.rows[r].set(lane * 2, VERT, gray);
    }
    if lane != head_lane {
        let row = &mut graph.rows[head_row];
        let (lo, hi) = if lane > head_lane {
            (head_lane, lane)
        } else {
            (lane, head_lane)
        };
        for pos in (lo * 2 + 1)..(hi * 2) {
            if pos % 2 == 1 {
                row.set(pos, HORZ, gray);
            } else {
                match row.get(pos) {
                    Some(cell) if cell.ch == VERT => row.set(pos, CROSS, cell.color),
                    Some(_) => {}
                    None => row.set(pos, HORZ, gray),
                }
            }
        }
        row.set(lane * 2, CORNER_UP_LEFT, gray);
    }
    let mut top = GraphRow::new(graph.lanes * 2);
    top.lane = lane;
    top.set(lane * 2, NODE, gray);
    graph.rows.insert(0, top);
    true
}

pub fn commit_rows(graph: &Graph) -> HashMap<usize, usize> {
    let mut m = HashMap::new();
    for (ri, r) in graph.rows.iter().enumerate() {
        if let Some(ci) = r.commit {
            m.insert(ci, ri);
        }
    }
    m
}
