//! Fuzzy matching for branch names.

const START: i32 = 36;
const SLASH: i32 = 18;
const SEP: i32 = 16;
const CAMEL: i32 = 10;
const PLAIN: i32 = 0;
const CONSEC: i32 = 16;
const GAP: i32 = 2;

const START_MM: i32 = 33;
const SLASH_MM: i32 = 14;
const SEP_MM: i32 = 11;
const PLAIN_MM: i32 = -2;
const CONSEC_MM: i32 = 11;

#[derive(Debug, Clone)]
pub struct FuzzyMatch {
    pub score: i32,
    pub positions: Vec<usize>,
}

#[derive(Clone, Copy, PartialEq)]
enum Kind {
    Start,
    Slash,
    Sep,
    Camel,
    Plain,
}

fn kind_at(chars: &[char], i: usize) -> Kind {
    if i == 0 {
        return Kind::Start;
    }
    let prev = chars[i - 1];
    let cur = chars[i];
    if prev == '/' {
        Kind::Slash
    } else if prev == '-' || prev == '_' || prev == '.' {
        Kind::Sep
    } else if cur.is_uppercase() && !prev.is_uppercase() {
        Kind::Camel
    } else {
        Kind::Plain
    }
}

fn char_score(kind: Kind, mismatch: bool, consecutive: bool) -> i32 {
    let (bonus, consec) = if mismatch && kind != Kind::Camel {
        let b = match kind {
            Kind::Start => START_MM,
            Kind::Slash => SLASH_MM,
            Kind::Sep => SEP_MM,
            Kind::Plain => PLAIN_MM,
            Kind::Camel => CAMEL,
        };
        (b, CONSEC_MM)
    } else {
        let b = match kind {
            Kind::Start => START,
            Kind::Slash => SLASH,
            Kind::Sep => SEP,
            Kind::Camel => CAMEL,
            Kind::Plain => PLAIN,
        };
        (b, CONSEC)
    };
    if consecutive {
        bonus.max(consec)
    } else {
        bonus
    }
}

fn lower(c: char) -> char {
    c.to_lowercase().next().unwrap_or(c)
}

pub fn fuzzy_match(query: &str, target: &str) -> Option<FuzzyMatch> {
    let q: Vec<char> = query.chars().collect();
    let t: Vec<char> = target.chars().collect();
    if q.is_empty() || t.is_empty() || q.len() > t.len() {
        return None;
    }
    let ql: Vec<char> = q.iter().map(|&c| lower(c)).collect();
    let tl: Vec<char> = t.iter().map(|&c| lower(c)).collect();
    let n = t.len();
    let m = q.len();
    let kinds: Vec<Kind> = (0..n).map(|i| kind_at(&t, i)).collect();

    // dp[k][i]: best score with query[k] matched at target position i
    let mut dp: Vec<Vec<Option<i32>>> = vec![vec![None; n]; m];
    let mut back: Vec<Vec<usize>> = vec![vec![0; n]; m];
    for i in 0..n {
        if tl[i] == ql[0] {
            dp[0][i] = Some(char_score(kinds[i], t[i] != q[0], false));
        }
    }
    for k in 1..m {
        for i in k..n {
            if tl[i] != ql[k] {
                continue;
            }
            let mut best: Option<(i32, usize)> = None;
            for j in 0..i {
                if let Some(prev) = dp[k - 1][j] {
                    let consecutive = i == j + 1;
                    let gap = if consecutive { 0 } else { (i - j - 1) as i32 };
                    let s = prev + char_score(kinds[i], t[i] != q[k], consecutive) - GAP * gap;
                    match best {
                        Some((bs, _)) if bs >= s => {}
                        _ => best = Some((s, j)),
                    }
                }
            }
            if let Some((s, j)) = best {
                dp[k][i] = Some(s);
                back[k][i] = j;
            }
        }
    }
    let mut best: Option<(i32, usize)> = None;
    for i in 0..n {
        if let Some(s) = dp[m - 1][i] {
            match best {
                Some((bs, _)) if bs >= s => {}
                _ => best = Some((s, i)),
            }
        }
    }
    let (score, mut i) = best?;
    let mut positions = vec![0; m];
    let mut k = m;
    while k > 0 {
        k -= 1;
        positions[k] = i;
        if k > 0 {
            i = back[k][i];
        }
    }
    Some(FuzzyMatch { score, positions })
}

/// Rank candidates: returns indices into `candidates` sorted by score (stable).
pub fn rank(query: &str, candidates: &[String]) -> Vec<(usize, FuzzyMatch)> {
    let mut out: Vec<(usize, FuzzyMatch)> = candidates
        .iter()
        .enumerate()
        .filter_map(|(i, c)| fuzzy_match(query, c).map(|m| (i, m)))
        .collect();
    out.sort_by(|a, b| b.1.score.cmp(&a.1.score));
    out
}
