    pub selected_branch: Option<String>,
    pub selected_key: Option<Oid>,
    pub last_summary: Option<DiffSummary>,
    /// global branch list in row order: (row index, entry)
    pub branch_list: Vec<(usize, BranchEntry)>,
    pub mode: Mode,
    pub message: Option<Message>,
    pub fetching: bool,
    pub fetch_rx: Option<Receiver<Result<(), String>>>,
    pub last_refresh: Instant,
    pub last_fetch: Instant,
    pub should_quit: bool,
}

impl App {
    pub fn new(git: Git, config: RefreshConfig) -> anyhow::Result<Self> {
        let data = git.load()?;
        let now = Instant::now();
        let mut app = App {
            git,
            config,
            data,
            rows: Vec::new(),
            lanes: 0,
            list_state: ListState::default(),
            selected: 0,
            selected_branch: None,
            selected_key: None,
            last_summary: None,
            branch_list: Vec::new(),
            mode: Mode::Normal,
            message: None,
            fetching: false,
            fetch_rx: None,
            last_refresh: now,
            last_fetch: now,
            should_quit: false,
        };
        app.rebuild_rows();
        app.selected = 0;
        app.list_state.select(if app.rows.is_empty() { None } else { Some(0) });
        app.on_row_changed();
        Ok(app)
    }

    fn head_branch_oid(&self) -> Option<Oid> {
        match &self.data.head {
            HeadState::Branch(_, oid) => Some(*oid),
            _ => None,
        }
    }

    pub fn rebuild_rows(&mut self) {
        let likes: Vec<graph::CommitLike> = self
            .data
            .commits
            .iter()
            .map(|c| graph::CommitLike {
                oid: c.oid,
                parents: &c.parents,
            })
            .collect();
        let mut g: Graph = graph::build(&likes, self.head_branch_oid());
        let mut rows: Vec<Row> = Vec::new();
        let mut uncommitted_inserted = false;
        if self.data.uncommitted_count > 0 {
            if let Some(head_oid) = self.data.head.oid() {
                if let Some(ci) = self.data.commits.iter().position(|c| c.oid == head_oid) {
                    let map = graph::commit_rows(&g);
                    if let Some(&hr) = map.get(&ci) {
                        uncommitted_inserted = graph::add_uncommitted(&mut g, hr);
                    }
                }
            }
        }
        for (ri, gr) in g.rows.iter().enumerate() {
            let kind = if uncommitted_inserted && ri == 0 {
                RowKind::Uncommitted(self.data.uncommitted_count)
            } else {
                match gr.commit {
                    Some(ci) => RowKind::Commit(ci),
                    None => RowKind::Connector,
                }
            };
            rows.push(Row {
                kind,
                graph: gr.clone(),
            });
        }
        self.lanes = g.lanes;
        self.rows = rows;
        // branch list
        let mut list = Vec::new();
        for (ri, row) in self.rows.iter().enumerate() {
            if let RowKind::Commit(ci) = row.kind {
                let oid = self.data.commits[ci].oid;
                if let Some(entries) = self.data.branches.get(&oid) {
                    for e in entries {
                        list.push((ri, e.clone()));
                    }
                }
            }
        }
        self.branch_list = list;
    }

    pub fn row_entries(&self, ri: usize) -> &[BranchEntry] {
        match self.rows.get(ri).map(|r| &r.kind) {
            Some(RowKind::Commit(ci)) => {
                let oid = self.data.commits[*ci].oid;
                self.data
                    .branches
                    .get(&oid)
                    .map(|v| v.as_slice())
                    .unwrap_or(&[])
            }
            _ => &[],
        }
    }

    pub fn current_commit_index(&self) -> Option<usize> {
        match self.rows.get(self.selected).map(|r| &r.kind) {
            Some(RowKind::Commit(ci)) => Some(*ci),
            _ => None,
        }
    }

    pub fn detail(&self) -> Detail {
        match self.rows.get(self.selected).map(|r| &r.kind) {
            Some(RowKind::Commit(ci)) => Detail::Commit(*ci),
            Some(RowKind::Uncommitted(_)) => Detail::Uncommitted,
            Some(RowKind::Connector) => Detail::Connector,
            None => Detail::None,
        }
    }

    /// Called after the selected row changed by navigation: update branch selection and detail.
    pub fn on_row_changed(&mut self) {
        let entries = self.row_entries(self.selected);
        self.selected_branch = entries.first().map(|e| e.name.clone());
        self.update_detail();
    }

    pub fn update_detail(&mut self) {
        match self.rows.get(self.selected).map(|r| r.kind.clone()) {
            Some(RowKind::Commit(ci)) => {
                let oid = self.data.commits[ci].oid;
                self.selected_key = Some(oid);
                self.last_summary = Some(self.git.commit_diff(oid).unwrap_or_default());
            }
            Some(RowKind::Uncommitted(_)) => {
                self.selected_key = None;
                self.last_summary = Some(self.git.uncommitted_diff().unwrap_or_default());
            }
            Some(RowKind::Connector) => {}
            None => {
                self.selected_key = None;
                self.last_summary = None;
            }
        }
    }

    pub fn select_row(&mut self, ri: usize) {
        if self.rows.is_empty() {
            self.selected = 0;
            self.list_state.select(None);
            return;
        }
        let ri = ri.min(self.rows.len() - 1);
        self.selected = ri;
        self.list_state.select(Some(ri));
        self.on_row_changed();
    }

    pub fn move_by(&mut self, delta: isize) {
        if self.rows.is_empty() {
            return;
        }
        let cur = self.selected as isize;
        let max = self.rows.len() as isize - 1;
        let next = (cur + delta).clamp(0, max);
        if next != cur {
            self.select_row(next as usize);
        }
    }

    pub fn jump_to_head(&mut self) {
        let Some(head_oid) = self.data.head.oid() else { return };
        let Some(ri) = self.rows.iter().position(|r| match r.kind {
            RowKind::Commit(ci) => self.data.commits[ci].oid == head_oid,
            _ => false,
        }) else {
            return;
        };
        self.select_row(ri);
        if let Some(name) = self.data.head.branch_name() {
            if self.row_entries(ri).iter().any(|e| e.name == name) {
                self.selected_branch = Some(name.to_string());
            }
        }
    }

    pub fn branch_left_right(&mut self, delta: isize) {
        let entries = self.row_entries(self.selected);
        let Some(cur) = &self.selected_branch else { return };
        let Some(idx) = entries.iter().position(|e| &e.name == cur) else { return };
        let max = entries.len() as isize - 1;
        let next = (idx as isize + delta).clamp(0, max) as usize;
        self.selected_branch = Some(entries[next].name.clone());
    }

    pub fn branch_next_prev(&mut self, forward: bool) {
        if self.branch_list.is_empty() {
            return;
        }
        let cur = self
            .selected_branch
            .as_ref()
            .and_then(|name| self.branch_list.iter().position(|(_, e)| &e.name == name));
        let next = match cur {
            Some(i) => {
                if forward {
                    (i + 1).min(self.branch_list.len() - 1)
                } else {
                    i.saturating_sub(1)
                }
            }
            None => {
                if forward {
                    0
                } else {
                    self.branch_list.len() - 1
                }
            }
        };
        let (ri, entry) = self.branch_list[next].clone();
        self.goto_branch(ri, &entry.name);
    }

    pub fn goto_branch(&mut self, ri: usize, name: &str) {
        if self.rows.is_empty() {
            return;
        }
        let ri = ri.min(self.rows.len() - 1);
        self.selected = ri;
        self.list_state.select(Some(ri));
        self.selected_branch = Some(name.to_string());
        self.update_detail();
    }

    pub fn refresh(&mut self) {
        let prev_key = self.selected_key;
        let prev_index = self.selected;
        match self.git.load() {
            Ok(data) => self.data = data,
            Err(_) => return,
        }
        self.rebuild_rows();
        if self.rows.is_empty() {
            self.selected = 0;
            self.list_state.select(None);
            self.selected_key = None;
            self.last_summary = None;
            return;
        }
        let found = prev_key.and_then(|key| {
            self.rows.iter().position(|r| match r.kind {
                RowKind::Commit(ci) => self.data.commits[ci].oid == key,
                _ => false,
            })
        });
        let ri = match found {
            Some(ri) => ri,
            None => prev_index.min(self.rows.len() - 1),
        };
        self.selected = ri;
        self.list_state.select(Some(ri));
        self.update_detail();
    }

    pub fn set_message(&mut self, text: &str, kind: MessageKind) {
        self.message = Some(Message {
            text: text.to_string(),
            kind,
            at: Instant::now(),
        });
    }

    pub fn tick(&mut self) {
        if let Some(m) = &self.message {
            if m.kind == MessageKind::Info && m.at.elapsed() >= MESSAGE_TTL {
                self.message = None;
            }
        }
        // fetch result
        if let Some(rx) = &self.fetch_rx {
            match rx.try_recv() {
                Ok(res) => {
                    self.fetching = false;
                    self.fetch_rx = None;
                    match res {
                        Ok(()) => {
                            self.set_message("Fetched from origin", MessageKind::Info);
                            self.refresh();
                        }
                        Err(e) => {
                            self.message = None;
                            self.mode = Mode::Error(format!("git fetch failed: {}", e));
                        }
                    }
                }
                Err(std::sync::mpsc::TryRecvError::Disconnected) => {
                    self.fetching = false;
                    self.fetch_rx = None;
                    self.message = None;
                }
                Err(std::sync::mpsc::TryRecvError::Empty) => {}
            }
        }
        if self.config.auto_refresh && self.last_refresh.elapsed() >= self.config.refresh_interval {
            self.last_refresh = Instant::now();
            self.refresh();
        }
        if self.config.auto_fetch && self.last_fetch.elapsed() >= self.config.fetch_interval {
            self.last_fetch = Instant::now();
            self.start_fetch();
        }
    }

    pub fn start_fetch(&mut self) {
        if self.fetching {
            return;
        }
        if self.git.repo.find_remote("origin").is_err() {
            return;
        }
        let dir = self
            .git
            .repo
            .workdir()
            .map(|p| p.to_path_buf())
            .unwrap_or_else(|| self.git.repo.path().to_path_buf());
        let (tx, rx) = channel();
        self.fetching = true;
        self.fetch_rx = Some(rx);
        self.set_message("Fetching from origin...", MessageKind::Progress);
        std::thread::spawn(move || {
            let out = std::process::Command::new("git")
                .args(["fetch", "origin"])
                .current_dir(&dir)
                .stdin(std::process::Stdio::null())
                .output();
            let res = match out {
                Ok(o) => {
                    if o.status.success() {
                        Ok(())
                    } else {
                        let s = String::from_utf8_lossy(&o.stderr).to_string();
                        let s: String = s.chars().filter(|&c| c != '\n' && c != '\r').collect();
                        Err(s.trim().to_string())
                    }
                }
                Err(e) => Err(e.to_string()),
            };
            let _ = tx.send(res);
        });
    }

    // ----- git operations -----

    pub fn checkout_selected(&mut self) {
        let Some(ci) = self.current_commit_index() else { return };
        let oid = self.data.commits[ci].oid;
        let entries = self.row_entries(self.selected).to_vec();
        let entry = self
            .selected_branch
            .as_ref()
            .and_then(|n| entries.iter().find(|e| &e.name == n))
            .cloned();
        let res = match entry {
            Some(e) if e.is_remote => self.git.checkout_remote_branch(&e.name, oid),
            Some(e) => self.git.checkout_local_branch(&e.name),
            None => self.git.checkout_commit(oid),
        };
        match res {
            Ok(()) => self.refresh(),
            Err(e) => self.mode = Mode::Error(root_message(&e)),
        }
    }

    pub fn create_branch(&mut self, name: &str) {
        let Some(ci) = self.current_commit_index() else { return };
        let oid = self.data.commits[ci].oid;
        match self.git.create_branch(name, oid) {
            Ok(()) => self.refresh(),
            Err(_) => self.mode = Mode::Error(format!("Failed to create branch '{}'", name)),
        }
    }

    pub fn deletable_branch(&self) -> Option<String> {
        let entries = self.row_entries(self.selected);
        let name = self.selected_branch.as_ref()?;
        let e = entries.iter().find(|e| &e.name == name)?;
        if e.is_remote || e.is_head {
            return None;
        }
        Some(e.name.clone())
    }

    pub fn delete_branch(&mut self, name: &str) {
        match self.git.delete_branch(name) {
            Ok(()) => self.refresh(),
            Err(_) => self.mode = Mode::Error(format!("Failed to delete branch '{}'", name)),
        }
    }

    // ----- search -----

    pub fn branch_names(&self) -> Vec<String> {
        self.branch_list.iter().map(|(_, e)| e.name.clone()).collect()
    }

    pub fn search_update(&mut self, st: &mut SearchState) {
        let names = self.branch_names();
        st.results = if st.query.is_empty() {
            Vec::new()
        } else {
            fuzzy::rank(&st.query, &names)
        };
        st.selected = 0;
        self.search_preview(st);
    }

    pub fn search_preview(&mut self, st: &SearchState) {
        if let Some((bi, _)) = st.results.get(st.selected) {
            let (ri, entry) = self.branch_list[*bi].clone();
            self.goto_branch(ri, &entry.name);
        }
    }

    pub fn dropdown_visible(&self) -> bool {
        matches!(self.mode, Mode::Normal) && self.row_entries(self.selected).len() >= 2
    }
}

pub fn root_message(e: &anyhow::Error) -> String {
    e.to_string()
}

pub fn head_label(head: &HeadState) -> Option<String> {
    match head {
        HeadState::Unborn => None,
        HeadState::Detached(_) => Some("HEAD".to_string()),
        HeadState::Branch(n, _) => Some(n.clone()),
    }
}
