            return;
        }
        let ri = ri.min(self.rows.len() - 1);
        self.selected = ri;
        self.list_state.select(Some(ri));
        self.selected_branch = Some(name.to_string());
        self.update_detail();
    }

    pub fn refresh(&mut self) {
        let prev_key = self.selected_key;
        let prev_index = self.selected;
        match self.git.load() {
            Ok(data) => self.data = data,
            Err(_) => return,
        }
        self.rebuild_rows();
        if self.rows.is_empty() {
            self.selected = 0;
            self.list_state.select(None);
            self.selected_key = None;
            self.last_summary = None;
            return;
        }
        let found = prev_key.and_then(|key| {
            self.rows.iter().position(|r| match r.kind {
                RowKind::Commit(ci) => self.data.commits[ci].oid == key,
                _ => false,
            })
        });
        let ri = match found {
            Some(ri) => ri,
            None => prev_index.min(self.rows.len() - 1),
        };
        self.selected = ri;
        self.list_state.select(Some(ri));
        self.update_detail();
    }

    pub fn set_message(&mut self, text: &str, kind: MessageKind) {
        self.message = Some(Message {
            text: text.to_string(),
            kind,
            at: Instant::now(),
        });
    }

    pub fn tick(&mut self) {
        if let Some(m) = &self.message {
            if m.kind == MessageKind::Info && m.at.elapsed() >= MESSAGE_TTL {
                self.message = None;
            }
        }
        // fetch result
        if let Some(rx) = &self.fetch_rx {
            match rx.try_recv() {
                Ok(res) => {
                    self.fetching = false;
                    self.fetch_rx = None;
                    match res {
                        Ok(()) => {
                            self.set_message("Fetched from origin", MessageKind::Info);
                            self.refresh();
                        }
                        Err(e) => {
                            self.message = None;
                            self.mode = Mode::Error(format!("git fetch failed: {}", e));
                        }
                    }
                }
                Err(std::sync::mpsc::TryRecvError::Disconnected) => {
                    self.fetching = false;
                    self.fetch_rx = None;
                    self.message = None;
                }
                Err(std::sync::mpsc::TryRecvError::Empty) => {}
            }
        }
        if self.config.auto_refresh && self.last_refresh.elapsed() >= self.config.refresh_interval {
            self.last_refresh = Instant::now();
            self.refresh();
        }
        if self.config.auto_fetch && self.last_fetch.elapsed() >= self.config.fetch_interval {
            self.last_fetch = Instant::now();
            self.start_fetch();
        }
    }

    pub fn start_fetch(&mut self) {
        if self.fetching {
            return;
        }
        if self.git.repo.find_remote("origin").is_err() {
            return;
        }
        let dir = self
            .git
            .repo
            .workdir()
            .map(|p| p.to_path_buf())
            .unwrap_or_else(|| self.git.repo.path().to_path_buf());
        let (tx, rx) = channel();
        self.fetching = true;
        self.fetch_rx = Some(rx);
        self.set_message("Fetching from origin...", MessageKind::Progress);
        std::thread::spawn(move || {
            let out = std::process::Command::new("git")
                .args(["fetch", "origin"])
                .current_dir(&dir)
                .stdin(std::process::Stdio::null())
                .output();
            let res = match out {
                Ok(o) => {
                    if o.status.success() {
                        Ok(())
                    } else {
                        let s = String::from_utf8_lossy(&o.stderr).to_string();
                        let s: String = s.chars().filter(|&c| c != '\n' && c != '\r').collect();
                        Err(s.trim().to_string())
                    }
                }
                Err(e) => Err(e.to_string()),
            };
            let _ = tx.send(res);
        });
    }

    // ----- git operations -----

    pub fn checkout_selected(&mut self) {
        let Some(ci) = self.current_commit_index() else { return };
        let oid = self.data.commits[ci].oid;
        let entries = self.row_entries(self.selected).to_vec();
        let entry = self
            .selected_branch
            .as_ref()
            .and_then(|n| entries.iter().find(|e| &e.name == n))
            .cloned();
        let res = match entry {
            Some(e) if e.is_remote => self.git.checkout_remote_branch(&e.name, oid),
            Some(e) => self.git.checkout_local_branch(&e.name),
            None => self.git.checkout_commit(oid),
        };
        match res {
            Ok(()) => self.refresh(),
            Err(e) => self.mode = Mode::Error(root_message(&e)),
        }
    }

    pub fn create_branch(&mut self, name: &str) {
        let Some(ci) = self.current_commit_index() else { return };
        let oid = self.data.commits[ci].oid;
        match self.git.create_branch(name, oid) {
            Ok(()) => self.refresh(),
            Err(_) => self.mode = Mode::Error(format!("Failed to create branch '{}'", name)),
        }
    }

    pub fn deletable_branch(&self) -> Option<String> {
        let entries = self.row_entries(self.selected);
        let name = self.selected_branch.as_ref()?;
        let e = entries.iter().find(|e| &e.name == name)?;
        if e.is_remote || e.is_head {
            return None;
        }
        Some(e.name.clone())
    }

    pub fn delete_branch(&mut self, name: &str) {
        match self.git.delete_branch(name) {
            Ok(()) => self.refresh(),
            Err(_) => self.mode = Mode::Error(format!("Failed to delete branch '{}'", name)),
        }
    }

    // ----- search -----

    pub fn branch_names(&self) -> Vec<String> {
        self.branch_list.iter().map(|(_, e)| e.name.clone()).collect()
    }

    pub fn search_update(&mut self, st: &mut SearchState) {
        let names = self.branch_names();
        st.results = if st.query.is_empty() {
            Vec::new()
        } else {
            fuzzy::rank(&st.query, &names)
        };
        st.selected = 0;
        self.search_preview(st);
    }

    pub fn search_preview(&mut self, st: &SearchState) {
        if let Some((bi, _)) = st.results.get(st.selected) {
            let (ri, entry) = self.branch_list[*bi].clone();
            self.goto_branch(ri, &entry.name);
        }
    }

    pub fn dropdown_visible(&self) -> bool {
        matches!(self.mode, Mode::Normal) && self.row_entries(self.selected).len() >= 2
    }
}

pub fn root_message(e: &anyhow::Error) -> String {
    e.to_string()
}

pub fn head_label(head: &HeadState) -> Option<String> {
    match head {
        HeadState::Unborn => None,
        HeadState::Detached(_) => Some("HEAD".to_string()),
        HeadState::Branch(n, _) => Some(n.clone()),
    }
}
