                ("l / \u{2192}", "Select right branch (same commit)"),
                ("Ctrl+d", "Page down"),
                ("Ctrl+u", "Page up"),
                ("g / Home", "Go to top"),
                ("G / End", "Go to bottom"),
                ("@", "Jump to HEAD (current branch)"),
            ],
        ),
        (
            "Git Operations",
            &[
                ("Enter", "Checkout selected branch/commit"),
                ("b", "Create new branch"),
                ("d", "Delete branch"),
                ("f", "Fetch from origin"),
            ],
        ),
        (
            "Search",
            &[
                ("/", "Search branches"),
                ("\u{2191} / C-k", "Select previous result"),
                ("\u{2193} / C-j", "Select next result"),
                ("Enter", "Jump to selected branch"),
                ("Esc", "Cancel search"),
            ],
        ),
        (
            "Other",
