fn draw_search(frame: &mut Frame, app: &App, area: Rect, st: &crate::app::SearchState) {
    let width = (area.width as u32 * 60 / 100) as u16;
    let x = (area.width - width) / 2;
    let gray = Style::default().fg(Color::DarkGray);
    let mut lines: Vec<Line> = Vec::new();
    lines.push(Line::from(vec![
        Span::raw("  "),
        Span::styled(
            st.query.clone(),
            Style::default()
                .fg(Color::White)
                .add_modifier(Modifier::UNDERLINED),
        ),
        Span::styled("_", Style::default().fg(Color::Cyan)),
    ]));
    if st.query.is_empty() {
        lines.push(Line::from(Span::styled(
            "  Enter: confirm  Esc: cancel",
            gray,
        )));
    } else if st.results.is_empty() {
        lines.push(Line::from(Span::styled("  No matches", gray)));
    } else {
        let inner_w = width.saturating_sub(2) as usize;
        lines.push(Line::from(Span::styled(
            "\u{2500}".repeat(inner_w),
            gray,
        )));
        let n = st.results.len();
        let visible = n.min(SEARCH_VISIBLE);
        let offset = st.selected.saturating_sub(SEARCH_VISIBLE - 1);
        let offset = offset.min(n.saturating_sub(visible));
        for vi in 0..visible {
            let idx = offset + vi;
            let (bi, m) = &st.results[idx];
            let name = &app.branch_list[*bi].1.name;
            let is_sel = idx == st.selected;
            let more_above = vi == 0 && offset > 0;
            let more_below = vi + 1 == visible && offset + visible < n;
            let mut spans: Vec<Span> = Vec::new();
            if is_sel {
                let prefix = if more_below {
                    "\u{25bc} "
                } else if more_above {
                    "\u{25b2} "
                } else {
                    "\u{25b6} "
                };
                spans.push(Span::styled(prefix, Style::default().fg(Color::Cyan)));
                spans.push(Span::styled(
                    name.clone(),
                    Style::default()
                        .fg(Color::Black)
                        .bg(Color::Cyan)
                        .add_modifier(Modifier::BOLD),
                ));
            } else {
                let prefix = if more_above {
                    "\u{2191} "
                } else if more_below {
                    "\u{2193} "
                } else {
                    "  "
                };
                spans.push(Span::styled(prefix, gray));
                let chars: Vec<char> = name.chars().collect();
                let mut cur = String::new();
                let mut cur_hl = false;
                for (i, ch) in chars.iter().enumerate() {
                    let hl = m.positions.contains(&i);
                    if hl != cur_hl && !cur.is_empty() {
                        spans.push(hl_span(std::mem::take(&mut cur), cur_hl));
                    }
                    cur_hl = hl;
                    cur.push(*ch);
                }
                if !cur.is_empty() {
                    spans.push(hl_span(cur, cur_hl));
                }
            }
            lines.push(Line::from(spans));
        }
        lines.push(Line::from(Span::styled(
            "  \u{2191}\u{2193}: select  Enter: jump  Esc: cancel",
            gray,
        )));
    }
    let height = (lines.len() + 2) as u16;
    let y = area.height.saturating_sub(1 + height);
    let rect = Rect::new(area.x + x, area.y + y, width, height.min(area.height));
    frame.render_widget(Clear, rect);
    let block = popup_block(" Search branches ", Color::Cyan);
    frame.render_widget(Paragraph::new(lines).block(block), rect);
}

fn hl_span(text: String, hl: bool) -> Span<'static> {
    if hl {
        Span::styled(
            text,
            Style::default()
                .fg(Color::Yellow)
                .add_modifier(Modifier::BOLD),
        )
    } else {
        Span::styled(text, Style::default().fg(Color::White))
    }
}

fn draw_dropdown(frame: &mut Frame, app: &App, list_area: Rect) {
    let entries = app.row_entries(app.selected);
    if entries.len() < 2 {
        return;
    }
    let inner = Rect::new(
        list_area.x + 1,
        list_area.y + 1,
        list_area.width.saturating_sub(2),
        list_area.height.saturating_sub(2),
    );
    let max_name = entries.iter().map(|e| e.name.width()).max().unwrap_or(0);
    let width = (max_name + 6) as u16;
    let n = entries.len().min(DROPDOWN_MAX);
    let height = (n + 2) as u16;
    let offset = app.list_state.offset();
    let v = app.selected.saturating_sub(offset) as u16;
    let mut y = inner.y + v + 1;
    if (v as usize) + 1 > height as usize {
        y = inner.y;
    } else if y + height > list_area.bottom() {
        if let Some(ny) = list_area.bottom().checked_sub(height) {
            if ny >= inner.y {
                y = ny;
            }
        }
    }
    let right = inner.right().saturating_sub(1);
    let x = right.saturating_sub(width);
    let rect = Rect::new(x, y, width, height);
    frame.render_widget(Clear, rect);
    let block = popup_block(" Branches ", Color::Blue);
    let mut lines: Vec<Line> = Vec::new();
    for e in entries.iter().take(n) {
        let is_sel = app.selected_branch.as_deref() == Some(e.name.as_str());
        if is_sel {
            lines.push(Line::from(Span::styled(
                format!("\u{25b6} {}", e.name),
                Style::default()
                    .fg(Color::Black)
                    .bg(Color::Blue)
                    .add_modifier(Modifier::BOLD),
            )));
        } else {
            lines.push(Line::from(Span::styled(
                format!("  {}", e.name),
                Style::default().fg(Color::White),
            )));
        }
    }
    frame.render_widget(Paragraph::new(lines).block(block), rect);
}
