use crate::app::{App, Detail, Mode, MessageKind, RowKind, DROPDOWN_MAX, SEARCH_VISIBLE};
use crate::git::{BranchEntry, DiffSummary};
use chrono::{Local, TimeZone};
use ratatui::layout::{Constraint, Direction, Layout, Rect};
use ratatui::style::{Color, Modifier, Style};
use ratatui::text::{Line, Span};
use ratatui::widgets::{Block, Borders, Clear, List, ListItem, Paragraph, Wrap};
use ratatui::Frame;
use unicode_width::UnicodeWidthChar;
use unicode_width::UnicodeWidthStr;

pub const MIN_MSG_WIDTH: usize = 50;

pub fn draw(frame: &mut Frame, app: &mut App) {
    let area = frame.area();
    if area.width < 20 || area.height < 6 {
        let text = format!(
            "Terminal too small ({}x{}). Need at least 20x6.",
            area.width, area.height
        );
        let p = Paragraph::new(Line::from(Span::styled(text, Style::default().fg(Color::Red))));
