        Mode::Confirm(name) => draw_confirm(frame, area, &name),
        Mode::Search(st) => draw_search(frame, app, area, &st),
    }
}

fn gray_block(title: &str) -> Block<'static> {
    Block::default()
        .borders(Borders::ALL)
        .border_style(Style::default().fg(Color::DarkGray))
        .title(Span::styled(
            title.to_string(),
            Style::default().fg(Color::DarkGray),
        ))
}

fn truncate_width(s: &str, width: usize) -> (String, usize) {
    let mut out = String::new();
    let mut w = 0;
    for ch in s.chars() {
        let cw = ch.width().unwrap_or(0);
        if w + cw > width {
            break;
        }
        out.push(ch);
        w += cw;
    }
    (out, w)
}

fn fit_width(s: &str, width: usize) -> String {
    let (mut out, w) = truncate_width(s, width);
    for _ in w..width {
        out.push(' ');
    }
    out
}

fn format_date(ts: i64) -> String {
    match Local.timestamp_opt(ts, 0).single() {
        Some(dt) => dt.format("%Y-%m-%d").to_string(),
        None => String::new(),
    }
}

fn format_datetime(ts: i64) -> String {
    match Local.timestamp_opt(ts, 0).single() {
        Some(dt) => dt.format("%Y-%m-%d %H:%M:%S").to_string(),
        None => String::new(),
    }
}

fn label_text(entries: &[BranchEntry], selected: Option<&str>) -> Option<(String, String)> {
    if entries.is_empty() {
        return None;
    }
    let idx = selected
        .and_then(|s| entries.iter().position(|e| e.name == s))
        .unwrap_or(0);
    let e = &entries[idx];
    let text = if entries.len() == 1 {
        format!("[{}]", e.display_name())
    } else {
        format!("[{}] +{}", e.name, entries.len() - 1)
    };
    Some((text, e.name.clone()))
}

fn draw_commits(frame: &mut Frame, app: &mut App, area: Rect) {
    let block = gray_block(" Commits ");
    let inner = block.inner(area);
    let inner_w = inner.width as usize;
    let prefix_w = 1 + app.lanes * 2 + 1;

    let mut items: Vec<ListItem> = Vec::with_capacity(app.rows.len());
    let selected = app.selected;
    for (ri, row) in app.rows.iter().enumerate() {
        let mut spans: Vec<Span> = Vec::new();
        spans.push(Span::raw(" "));
        for cell in &row.graph.cells {
            match cell {
                Some(c) => spans.push(Span::styled(
                    c.ch.to_string(),
                    Style::default().fg(c.color).add_modifier(Modifier::BOLD),
                )),
                None => spans.push(Span::styled(" ", Style::default().add_modifier(Modifier::BOLD))),
            }
        }
        spans.push(Span::raw(" "));
        match &row.kind {
            RowKind::Uncommitted(n) => {
                spans.push(Span::styled(
                    format!("uncommitted changes ({})", n),
                    Style::default().fg(Color::White),
                ));
            }
            RowKind::Connector => {}
            RowKind::Commit(ci) => {
                let commit = &app.data.commits[*ci];
                let entries = app.row_entries(ri);
                let avail = inner_w.saturating_sub(prefix_w);
                let date = format_date(commit.time);
                let author = fit_width(&commit.author_name, 8);
                let hash = commit.short.clone();
                // decide columns
                let (show_date, show_author, show_hash, right_w) = if avail >= MIN_MSG_WIDTH + 31 {
                    (true, true, true, 31)
                } else if avail >= MIN_MSG_WIDTH + 22 {
                    (true, true, false, 22)
                } else if avail >= MIN_MSG_WIDTH + 11 {
                    (false, true, false, 11)
                } else {
                    (false, false, false, 0)
                };
                let msg_w = avail.saturating_sub(right_w);
                let lane_color = row
                    .graph
                    .cells
                    .get(row.graph.lane * 2)
                    .and_then(|c| c.map(|c| c.color))
                    .unwrap_or(Color::Reset);
                let mut segs: Vec<(String, Style)> = Vec::new();
                if let Some((label, name)) = label_text(entries, app.selected_branch.as_deref()) {
                    let style = if ri == selected && app.selected_branch.as_deref() == Some(name.as_str()) {
                        Style::default().fg(Color::Black)
                    } else {
                        Style::default().fg(lane_color).add_modifier(Modifier::BOLD)
                    };
                    segs.push((label, style));
                    segs.push((format!(" {}", commit.summary), Style::default()));
                } else {
                    segs.push((commit.summary.clone(), Style::default()));
                }
                // truncate segments to msg_w
                let mut remaining = msg_w;
                for (text, style) in segs {
                    if remaining == 0 {
                        break;
                    }
                    let (t, w) = truncate_width(&text, remaining);
                    remaining -= w;
                    if !t.is_empty() {
                        spans.push(Span::styled(t, style));
                    }
                }
                if remaining > 0 {
                    spans.push(Span::raw(" ".repeat(remaining)));
                }
                if show_date {
                    spans.push(Span::raw(" "));
                    spans.push(Span::styled(date, Style::default().fg(Color::DarkGray)));
                }
                if show_author {
                    spans.push(Span::raw("  "));
                    spans.push(Span::styled(author, Style::default().fg(Color::Cyan)));
                }
                if show_hash {
                    spans.push(Span::raw("  "));
                    spans.push(Span::styled(hash, Style::default().fg(Color::Yellow)));
                }
                if right_w > 0 {
                    spans.push(Span::raw(" "));
                }
            }
        }
        items.push(ListItem::new(Line::from(spans)));
    }
    let list = List::new(items).block(block).highlight_style(
        Style::default()
            .bg(Color::DarkGray)
            .add_modifier(Modifier::BOLD),
    );
    frame.render_stateful_widget(list, area, &mut app.list_state);
}

fn draw_detail(frame: &mut Frame, app: &App, area: Rect) {
    let block = gray_block(" Commit Detail ");
    let gray = Style::default().fg(Color::DarkGray);
    let bold = Style::default().add_modifier(Modifier::BOLD);
    let mut lines: Vec<Line> = Vec::new();
    match app.detail() {
        Detail::None => lines.push(Line::from(Span::styled("Select a commit", gray))),
        Detail::Connector => lines.push(Line::from(Span::styled("(connector line)", gray))),
        Detail::Uncommitted => {
            lines.push(Line::from(Span::styled(
                "Uncommitted Changes",
                Style::default().fg(Color::DarkGray).add_modifier(Modifier::BOLD),
            )));
            lines.push(Line::from(""));
            let n = app.data.uncommitted_count;
            lines.push(Line::from(Span::styled(
                format!("{} files with changes", n),
                gray,
            )));
        }
        Detail::Commit(ci) => {
            let c = &app.data.commits[ci];
            lines.push(Line::from(vec![
                Span::styled("Commit: ", bold),
                Span::styled(c.oid.to_string(), Style::default().fg(Color::Yellow)),
            ]));
            lines.push(Line::from(vec![
                Span::styled("Author: ", bold),
                Span::styled(
                    format!("{} <{}>", c.author_name, c.author_email),
                    Style::default().fg(Color::Blue),
                ),
            ]));
            lines.push(Line::from(vec![
                Span::styled("Date:   ", bold),
                Span::styled(format_datetime(c.time), gray),
            ]));
            if !c.parents.is_empty() {
                let parents: Vec<String> = c
                    .parents
                    .iter()
                    .map(|p| p.to_string().chars().take(7).collect())
                    .collect();
                lines.push(Line::from(vec![
                    Span::styled("Parent: ", bold),
                    Span::styled(parents.join(", "), gray),
                ]));
            }
            lines.push(Line::from(""));
            for l in c.message.lines() {
                lines.push(Line::from(l.to_string()));
            }
        }
    }
    let p = Paragraph::new(lines).block(block).wrap(Wrap { trim: false });
    frame.render_widget(p, area);
}

fn status_style(status: char) -> Style {
    match status {
        'A' => Style::default().fg(Color::Green),
        'M' => Style::default().fg(Color::Yellow),
        'D' => Style::default().fg(Color::Red),
        'R' => Style::default().fg(Color::Cyan),
        'T' => Style::default().fg(Color::Magenta),
        _ => Style::default().fg(Color::White),
    }
}

fn draw_files(frame: &mut Frame, app: &App, area: Rect) {
    let block = gray_block(" Changed Files ");
    let mut lines: Vec<Line> = Vec::new();
    let summary: Option<&DiffSummary> = app.last_summary.as_ref();
    if let Some(s) = summary {
        lines.push(Line::from(vec![
            Span::styled(
                format!("{} files changed", s.files_changed),
                Style::default().add_modifier(Modifier::BOLD),
            ),
            Span::raw("  "),
            Span::styled(format!("+{}", s.insertions), Style::default().fg(Color::Green)),
            Span::raw(" "),
            Span::styled(format!("-{}", s.deletions), Style::default().fg(Color::Red)),
        ]));
        lines.push(Line::from(""));
        for f in &s.files {
            let mut spans = vec![
                Span::styled(format!(" {} ", f.status), status_style(f.status)),
            ];
            match f.stats {
                Some((a, d)) => {
                    spans.push(Span::raw(format!("{} ", f.path)));
                    spans.push(Span::styled(format!("+{}", a), Style::default().fg(Color::Green)));
                    spans.push(Span::raw(" "));
                    spans.push(Span::styled(format!("-{}", d), Style::default().fg(Color::Red)));
                }
                None => {
                    spans.push(Span::raw(f.path.clone()));
                }
            }
            lines.push(Line::from(spans));
        }
        if s.more > 0 {
            lines.push(Line::from(Span::styled(
                format!("  ...and {} more files", s.more),
                Style::default().fg(Color::DarkGray),
            )));
        }
    }
    let p = Paragraph::new(lines).block(block).wrap(Wrap { trim: false });
    frame.render_widget(p, area);
}

fn key_span(k: &str) -> Span<'static> {
    Span::styled(
        format!(" {} ", k),
        Style::default()
            .fg(Color::Black)
            .bg(Color::Cyan)
            .add_modifier(Modifier::BOLD),
    )
}

fn desc_span(d: &str, last: bool) -> Span<'static> {
    let text = if last { d.to_string() } else { format!("{} ", d) };
    Span::styled(text, Style::default().fg(Color::White))
}

fn hints(pairs: &[(&str, &str)]) -> Vec<Span<'static>> {
    let mut v = Vec::new();
    let n = pairs.len();
    for (i, (k, d)) in pairs.iter().enumerate() {
        v.push(key_span(k));
        v.push(desc_span(d, i + 1 == n));
    }
    v
}

fn draw_status(frame: &mut Frame, app: &App, area: Rect) {
    let mut spans: Vec<Span> = Vec::new();
    spans.push(Span::styled(
        format!(" {} ", app.data.repo_name),
        Style::default()
            .fg(Color::Black)
            .bg(Color::Magenta)
            .add_modifier(Modifier::BOLD),
    ));
    spans.push(Span::raw(" "));
    if let Some(b) = crate::app::head_label(&app.data.head) {
        spans.push(Span::styled(
            format!(" {} ", b),
            Style::default().fg(Color::Black).bg(Color::Green),
        ));
        spans.push(Span::raw(" "));
    }
    let mut right: Option<&str> = None;
    match &app.mode {
        Mode::Error(msg) => {
            spans.push(Span::styled(
                format!(" {} ", msg),
                Style::default()
                    .fg(Color::White)
                    .bg(Color::Red)
                    .add_modifier(Modifier::BOLD),
            ));
            spans.push(Span::raw("  "));
            spans.extend(hints(&[("Esc/Enter", "close")]));
            right = Some(" ERROR ");
        }
        Mode::Help => {
            spans.extend(hints(&[("Esc/q", "close help")]));
            right = Some(" HELP ");
        }
        Mode::Input(_) | Mode::Search(_) => {
            spans.extend(hints(&[("Enter", "confirm"), ("Esc", "cancel")]));
            right = Some(" INPUT ");
        }
        Mode::Confirm(_) => {
            spans.extend(hints(&[("y", "yes"), ("n", "no")]));
            right = Some(" CONFIRM ");
        }
        Mode::Normal => {
            if let Some(m) = &app.message {
                let bg = match m.kind {
                    MessageKind::Info => Color::Cyan,
                    MessageKind::Progress => Color::Yellow,
                };
                spans.push(Span::styled(
                    format!(" {} ", m.text),
                    Style::default()
                        .fg(Color::Black)
                        .bg(bg)
                        .add_modifier(Modifier::BOLD),
                ));
            } else {
                spans.extend(hints(&[
                    ("j/k", "move"),
                    ("Enter", "checkout"),
                    ("b", "branch"),
                    ("f", "fetch"),
                    ("?", "help"),
                    ("q", "quit"),
                ]));
            }
        }
    }
    frame.render_widget(Paragraph::new(Line::from(spans)), area);
    if let Some(r) = right {
        let w = r.width() as u16;
        if area.width >= w {
            let ra = Rect::new(area.x + area.width - w, area.y, w, 1);
            frame.render_widget(
                Paragraph::new(Line::from(Span::styled(
                    r.to_string(),
                    Style::default()
                        .fg(Color::Black)
                        .bg(Color::Yellow)
                        .add_modifier(Modifier::BOLD),
                ))),
                ra,
            );
        }
    }
}

pub fn centered_rect(percent_x: u16, percent_y: u16, r: Rect) -> Rect {
    let v = Layout::default()
        .direction(Direction::Vertical)
        .constraints([
            Constraint::Percentage((100 - percent_y) / 2),
            Constraint::Percentage(percent_y),
            Constraint::Percentage((100 - percent_y) / 2),
        ])
        .split(r);
    Layout::default()
        .direction(Direction::Horizontal)
        .constraints([
            Constraint::Percentage((100 - percent_x) / 2),
            Constraint::Percentage(percent_x),
            Constraint::Percentage((100 - percent_x) / 2),
        ])
        .split(v[1])[1]
}

fn popup_block(title: &str, border: Color) -> Block<'static> {
    Block::default()
        .borders(Borders::ALL)
        .border_style(Style::default().fg(border))
        .title(Span::styled(title.to_string(), Style::default().fg(border)))
        .style(Style::default().bg(Color::Black))
}

fn draw_help(frame: &mut Frame, area: Rect) {
    let rect = centered_rect(60, 70, area);
    frame.render_widget(Clear, rect);
    let block = popup_block(" Help ", Color::Cyan);
    let header = Style::default()
