        .add_modifier(Modifier::BOLD);
    let keyst = Style::default().add_modifier(Modifier::BOLD);
    let desc = Style::default().fg(Color::White);
    let mut lines: Vec<Line> = Vec::new();
    let sections: &[(&str, &[(&str, &str)])] = &[
        (
            "Navigation",
            &[
                ("j / \u{2193}", "Move down"),
                ("k / \u{2191}", "Move up"),
                ("] / Tab", "Select next branch"),
                ("[ / S-Tab", "Select previous branch"),
                ("h / \u{2190}", "Select left branch (same commit)"),
                ("l / \u{2192}", "Select right branch (same commit)"),
                ("Ctrl+d", "Page down"),
                ("Ctrl+u", "Page up"),
                ("g / Home", "Go to top"),
                ("G / End", "Go to bottom"),
                ("@", "Jump to HEAD (current branch)"),
            ],
        ),
        (
            "Git Operations",
            &[
                ("Enter", "Checkout selected branch/commit"),
                ("b", "Create new branch"),
                ("d", "Delete branch"),
                ("f", "Fetch from origin"),
            ],
        ),
        (
