    app.search_preview(st);
}

fn handle_normal(app: &mut App, key: KeyEvent, ctrl: bool) {
    match key.code {
        KeyCode::Char('q') | KeyCode::Esc => app.should_quit = true,
        KeyCode::Char('j') | KeyCode::Down => app.move_by(1),
        KeyCode::Char('k') | KeyCode::Up => app.move_by(-1),
        KeyCode::Char('d') if ctrl => app.move_by(app::PAGE as isize),
        KeyCode::Char('u') if ctrl => app.move_by(-(app::PAGE as isize)),
        KeyCode::Char('g') | KeyCode::Home => {
            if !app.rows.is_empty() && app.selected != 0 {
                app.select_row(0);
            }
        }
        KeyCode::Char('G') | KeyCode::End => {
            if !app.rows.is_empty() && app.selected != app.rows.len() - 1 {
                app.select_row(app.rows.len() - 1);
            }
        }
        KeyCode::Char('h') | KeyCode::Left => app.branch_left_right(-1),
        KeyCode::Char('l') | KeyCode::Right => app.branch_left_right(1),
        KeyCode::Char(']') | KeyCode::Tab => app.branch_next_prev(true),
        KeyCode::Char('[') | KeyCode::BackTab => app.branch_next_prev(false),
        KeyCode::Char('@') => app.jump_to_head(),
        KeyCode::Enter => app.checkout_selected(),
        KeyCode::Char('b') => app.mode = Mode::Input(String::new()),
        KeyCode::Char('d') => {
            if let Some(name) = app.deletable_branch() {
                app.mode = Mode::Confirm(name);
            }
        }
        KeyCode::Char('f') => app.start_fetch(),
        KeyCode::Char('/') => {
            let st = SearchState {
                query: String::new(),
                results: Vec::new(),
                selected: 0,
                orig_row: app.selected,
                orig_branch: app.selected_branch.clone(),
            };
            app.mode = Mode::Search(st);
        }
        KeyCode::Char('R') => app.refresh(),
        KeyCode::Char('?') => app.mode = Mode::Help,
        _ => {}
    }
}
